record.field:
{
            "type": "object",
            "properties": {
                "line_id": {"type": "integer", "description": "line_id de la factura"},
                "tax_id": {"type": "integer", "description": "tax_id de un impuesto de compra disponible"},
                "operation": {"type": "string", "description": "add para agregar, remove para quitar"},
                "reason": {"type": "string", "description": "Qué impuesto se ajusta, por qué y qué fuente lo justifica"},
                "rule_id": {"type": "integer", "description": "rule_id de la regla aprendida que lo respalda, 0 si no hay"}
            },
            "required": ["line_id", "tax_id", "operation", "reason", "rule_id"]
        }

{
            "type": "object",
            "properties": {
                "confidence": {"type": "number", "description": "Tu confianza en que la factura es correcta, entre 0 y 1"},
                "explanation": {"type": "string", "description": "Por cada impuesto: por qué se aplicó o no (por ejemplo, base no superada) y la regla o fuente que lo justifica"}
            },
            "required": ["confidence", "explanation"]
        }

{
            "type": "object",
            "properties": {
                "claim_code": {"type": "string", "description": "Código del concepto de reclamo del anexo técnico: 01 documento con inconsistencias, 02 mercancía no entregada totalmente, 03 mercancía no entregada parcialmente, 04 servicio no prestado"},
                "reason": {"type": "string", "description": "Diferencia que motiva el reclamo"}
            },
            "required": ["claim_code", "reason"]
        }
